insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('uy', '/flags/history/uy-1815.svg', '1815-01-01', '1820-01-22', 'Ligue fédérale d''Artigas', 'Artigas''s Federal League', 'Bannière de José Gervasio Artigas, héros de l''indépendance : la bande diagonale rouge du fédéralisme sur le bleu et blanc. Elle reste un symbole national.', 'The banner of José Gervasio Artigas, hero of independence: the red diagonal of federalism over blue and white. It remains a national symbol.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('uy', '/flags/history/uy-1825.svg', '1825-04-19', '1828-08-27', 'Drapeau des Trente-Trois Orientaux', 'Flag of the Thirty-Three Orientals', 'Arboré en 1825 par les « Trente-Trois Orientaux » débarqués pour libérer la Bande orientale du Brésil, avec la devise « Libertad o Muerte ».', 'Flown in 1825 by the "Thirty-Three Orientals" who landed to free the Banda Oriental from Brazil, with the motto "Libertad o Muerte".');
